begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) select ('81000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'finance-'||n||'@example.test' from generate_series(1,4) n;
insert into public.responsible_accounts(user_id) values('81000000-0000-0000-0000-000000000001'),('81000000-0000-0000-0000-000000000002');
insert into public.passengers(id,user_id,name,default_daily_rate)
select ('82000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'81000000-0000-0000-0000-000000000001','Financial fixture '||n,10 from generate_series(1,4) n;
insert into public.passengers(id,user_id,name,default_daily_rate) values('82000000-0000-0000-0000-000000000005','81000000-0000-0000-0000-000000000002','Foreign fixture',10);
insert into public.passenger_accounts(user_id,passenger_id,owner_user_id) values('81000000-0000-0000-0000-000000000003','82000000-0000-0000-0000-000000000001','81000000-0000-0000-0000-000000000001');
create function pg_temp.c(n integer) returns public.monthly_charges language sql as $$
 select c from public.monthly_charges c where passenger_id=('82000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid and reference_month='2025-01-01' $$;
create temporary table snapshots(label text primary key,event_id uuid,original jsonb);
grant select,insert on snapshots to authenticated;
set local role authenticated;
set local request.jwt.claim.sub='81000000-0000-0000-0000-000000000001';
insert into public.rides(user_id,passenger_id,ride_date,rate_charged) values
 (auth.uid(),'82000000-0000-0000-0000-000000000001','2025-01-01',10.10),
 (auth.uid(),'82000000-0000-0000-0000-000000000001','2025-01-31',20.20),
 (auth.uid(),'82000000-0000-0000-0000-000000000003','2025-01-01',0);
insert into public.received_rides(user_id,passenger_id,received_date,amount) values
 (auth.uid(),'82000000-0000-0000-0000-000000000001','2025-01-03',5.30),
 (auth.uid(),'82000000-0000-0000-0000-000000000002','2025-01-03',10.05);
select lives_ok($$select public.close_month('2025-01-01')$$,'transactional close');
select is((pg_temp.c(1)).total_amount,25.00::numeric,'multiple entries and exact cents');
select is((pg_temp.c(2)).total_amount,-10.05::numeric,'compensations only preserve negative sign');
select is((pg_temp.c(3)).total_amount,0::numeric,'zero total');
select ok((pg_temp.c(3)).paid,'zero is settled without obligation');
select is((pg_temp.c(3)).active_payment_id,null::uuid,'zero has no payment');
select is((public.recalculate_charge('82000000-0000-0000-0000-000000000004','2025-01-01')).total_amount,0::numeric,'recalculate nonexistent charge');
select is((select count(*) from public.monthly_charges),4::bigint,'history includes zero closing');
select throws_ok($$select public.pay_charge((pg_temp.c(3)).id,(pg_temp.c(3)).revision)$$,'23514','NO_OBLIGATION','cannot pay zero');
select throws_ok($$select public.cancel_charge_payment((pg_temp.c(3)).id,gen_random_uuid())$$,'23514','NO_OBLIGATION','cannot cancel zero');
select ok((public.pay_charge((pg_temp.c(1)).id,(pg_temp.c(1)).revision)).paid,'positive payment');
insert into snapshots select 'positive',id,to_jsonb(e) from public.monthly_charge_events e where id=(pg_temp.c(1)).active_payment_id;
select is((pg_temp.c(1)).paid_amount,25::numeric,'integral signed payment');
select ok((pg_temp.c(1)).paid_at is not null,'server payment time');
select lives_ok($$select public.pay_charge((pg_temp.c(1)).id,(pg_temp.c(1)).revision)$$,'duplicate payment idempotent');
select is((select count(*) from public.monthly_charge_events where kind='PAYMENT'),1::bigint,'one payment event');
select ok((public.recalculate_charge('82000000-0000-0000-0000-000000000001','2025-01-01')).paid,'same total stays paid');
select is((pg_temp.c(1)).active_payment_id,(select event_id from snapshots where label='positive'),'same payment retained');
update public.rides set rate_charged=11.10 where passenger_id='82000000-0000-0000-0000-000000000001' and ride_date='2025-01-01';
select is((pg_temp.c(1)).total_amount,26::numeric,'increase automatically reconciles existing charge');
select ok(not (pg_temp.c(1)).paid,'increase reopens pending');
select is((select count(*) from public.monthly_charge_events where kind='REOPEN'),1::bigint,'automatic reopening audited');
select is((select count(*) from public.monthly_charge_events where kind='CANCEL'),0::bigint,'automatic reopen is not manual cancellation');
select is((select to_jsonb(e) from public.monthly_charge_events e where id=(select event_id from snapshots where label='positive')),(select original from snapshots where label='positive'),'original settlement untouched');
select throws_ok($$select public.pay_charge((pg_temp.c(1)).id,1)$$,'40001','STALE_OBLIGATION','old version cannot be paid');
select ok((public.pay_charge((pg_temp.c(1)).id,(pg_temp.c(1)).revision)).paid,'pay increased obligation');
update public.rides set rate_charged=9.10 where passenger_id='82000000-0000-0000-0000-000000000001' and ride_date='2025-01-01';
select is((pg_temp.c(1)).total_amount,24::numeric,'reduction total');
select ok(not (pg_temp.c(1)).paid,'reduction reopens pending');
select ok((public.pay_charge((pg_temp.c(1)).id,(pg_temp.c(1)).revision)).paid,'pay reduced obligation');
update public.received_rides set amount=40.30 where passenger_id='82000000-0000-0000-0000-000000000001';
select is((pg_temp.c(1)).total_amount,-11::numeric,'positive to negative');
select ok(not (pg_temp.c(1)).paid,'direction change reopens pending');
select ok((public.pay_charge((pg_temp.c(1)).id,(pg_temp.c(1)).revision)).paid,'negative payment');
select is((pg_temp.c(1)).paid_amount,-11::numeric,'negative settlement sign preserved');
delete from public.received_rides where passenger_id='82000000-0000-0000-0000-000000000001';
select is((pg_temp.c(1)).total_amount,29.30::numeric,'rides only');
select ok(not (pg_temp.c(1)).paid,'negative to positive reopens');
select ok((public.pay_charge((pg_temp.c(1)).id,(pg_temp.c(1)).revision)).paid,'pay positive direction again');
delete from public.rides where passenger_id='82000000-0000-0000-0000-000000000001';
select is((pg_temp.c(1)).total_amount,0::numeric,'all entries deleted produces zero');
select ok((pg_temp.c(1)).paid,'paid to zero no obligation');
select is((pg_temp.c(1)).active_payment_id,null::uuid,'zero has no active payment');
select lives_ok($$select public.close_month('2025-01-01')$$,'recalculate includes existing zero charge');
select is((select count(*) from public.monthly_charges),4::bigint,'closing history retained after deletion');
select ok((public.pay_charge((pg_temp.c(2)).id,(pg_temp.c(2)).revision)).paid,'negative compensation obligation paid');
insert into snapshots select 'negative',id,to_jsonb(e) from public.monthly_charge_events e where id=(pg_temp.c(2)).active_payment_id;
select ok(not (public.cancel_charge_payment((pg_temp.c(2)).id,(select event_id from snapshots where label='negative'))).paid,'pay then cancel returns pending');
select is((pg_temp.c(2)).total_amount,-10.05::numeric,'cancel does not change debt');
select is((select count(*) from public.monthly_charge_events where kind='CANCEL'),1::bigint,'cancellation audit event');
select is((select signed_amount from public.monthly_charge_events where kind='CANCEL'),-10.05::numeric,'cancellation preserves direction');
select ok((select occurred_at is not null and user_id=auth.uid() and related_payment_id=(select event_id from snapshots where label='negative') from public.monthly_charge_events where kind='CANCEL'),'cancel time owner and link');
select is((select to_jsonb(e) from public.monthly_charge_events e where id=(select event_id from snapshots where label='negative')),(select original from snapshots where label='negative'),'cancel preserves original amount/time');
select lives_ok($$select public.cancel_charge_payment((pg_temp.c(2)).id,(select event_id from snapshots where label='negative'))$$,'duplicate cancel idempotent');
select is((select count(*) from public.monthly_charge_events where kind='CANCEL'),1::bigint,'one reversal only');
select ok((public.pay_charge((pg_temp.c(2)).id,(pg_temp.c(2)).revision)).paid,'repay after cancellation creates new version');
select throws_ok($$select public.cancel_charge_payment((pg_temp.c(2)).id,(select event_id from snapshots where label='negative'))$$,'40001','STALE_OBLIGATION','old cancellation cannot cancel newer payment');
select ok((pg_temp.c(2)).paid,'new payment survives stale cancel');
select is((select count(*) from public.received_rides where passenger_id='82000000-0000-0000-0000-000000000002'),1::bigint,'cancel preserved compensation');
select throws_ok($$update public.monthly_charge_events set signed_amount=1$$,'42501',null,'history update forbidden');
select throws_ok($$delete from public.monthly_charge_events$$,'42501',null,'history deletion forbidden');
select throws_ok($$insert into public.monthly_charge_events(monthly_charge_id) values(gen_random_uuid())$$,'42501',null,'history fabrication forbidden');
select throws_ok($$update public.monthly_charges set paid=true$$,'42501',null,'client cannot forge payment');
select throws_ok($$select public.recalculate_charge('82000000-0000-0000-0000-000000000005','2025-01-01')$$,'42501','FINANCIAL_FORBIDDEN','foreign passenger rejected');
select throws_ok($$select public.close_month('2025-01-02')$$,'23514','INVALID_COMPETENCE','noncanonical competence');
select throws_ok($$select public.close_month(null)$$,'23514','INVALID_COMPETENCE','null competence');
select throws_ok($$select public.close_month('infinity')$$,'23514','INVALID_COMPETENCE','infinite competence');
select is((select count(*) from public.close_month('2025-02-01')),0::bigint,'months independent no carry');
set local request.jwt.claim.sub='81000000-0000-0000-0000-000000000002';
select is((select count(*) from public.monthly_charge_events),0::bigint,'other owner cannot read history');
select throws_ok($$select public.pay_charge((select (original->>'monthly_charge_id')::uuid from snapshots where label='positive'),1)$$,'42501','FINANCIAL_FORBIDDEN','other owner cannot pay known foreign charge');
select throws_ok($$select public.cancel_charge_payment((select (original->>'monthly_charge_id')::uuid from snapshots where label='negative'),(select event_id from snapshots where label='negative'))$$,'42501','FINANCIAL_FORBIDDEN','other owner cannot cancel known foreign charge');
select throws_ok($$select public.recalculate_charge('82000000-0000-0000-0000-000000000001','2025-01-01')$$,'42501','FINANCIAL_FORBIDDEN','other owner cannot recalculate');
set local request.jwt.claim.sub='81000000-0000-0000-0000-000000000003';
select throws_ok($$select public.close_month('2025-01-01')$$,'42501','FINANCIAL_FORBIDDEN','passenger cannot close');
select throws_ok($$select public.pay_charge(gen_random_uuid(),1)$$,'42501','FINANCIAL_FORBIDDEN','passenger cannot pay');
select throws_ok($$select public.cancel_charge_payment(gen_random_uuid(),gen_random_uuid())$$,'42501','FINANCIAL_FORBIDDEN','passenger cannot cancel');
select is((select count(*) from public.monthly_charge_events),0::bigint,'passenger cannot read owner audit');
set local request.jwt.claim.sub='81000000-0000-0000-0000-000000000004';
select throws_ok($$select public.close_month('2025-01-01')$$,'42501','FINANCIAL_FORBIDDEN','unlinked cannot close');
select throws_ok($$select public.pay_charge(gen_random_uuid(),1)$$,'42501','FINANCIAL_FORBIDDEN','unlinked cannot pay');
select throws_ok($$select public.cancel_charge_payment(gen_random_uuid(),gen_random_uuid())$$,'42501','FINANCIAL_FORBIDDEN','unlinked cannot cancel');
reset role;
select ok(not has_function_privilege('anon','public.close_month(date)','EXECUTE'),'anon no close grant');
select ok(not has_function_privilege('anon','public.pay_charge(uuid,bigint)','EXECUTE'),'anon no pay grant');
select ok(not has_function_privilege('anon','public.cancel_charge_payment(uuid,uuid)','EXECUTE'),'anon no cancel grant');
select ok(not has_function_privilege('authenticated','public.reconcile_charge(uuid,uuid,date)','EXECUTE'),'internal reconcile inaccessible');
select ok(not has_function_privilege('authenticated','public.financial_owner()','EXECUTE'),'internal owner inaccessible');
select ok(not has_table_privilege('anon','public.monthly_charge_events','SELECT'),'anonymous history inaccessible');
select ok(not has_table_privilege('authenticated','public.monthly_charges','INSERT'),'no direct charge fabrication');
select ok(not has_table_privilege('authenticated','public.monthly_charges','DELETE'),'closing history cannot be deleted by clients');
select ok(not exists(select 1 from pg_proc p, lateral aclexplode(p.proacl) a where p.oid in ('public.close_month(date)'::regprocedure,'public.pay_charge(uuid,bigint)'::regprocedure,'public.cancel_charge_payment(uuid,uuid)'::regprocedure) and a.grantee=0 and a.privilege_type='EXECUTE'),'PUBLIC has no financial execution');
set local role anon;
select throws_ok($$select public.close_month('2025-01-01')$$,'42501',null,'anonymous cannot close');
select throws_ok($$select public.pay_charge(gen_random_uuid(),1)$$,'42501',null,'anonymous cannot pay');
select throws_ok($$select public.cancel_charge_payment(gen_random_uuid(),gen_random_uuid())$$,'42501',null,'anonymous cannot cancel');
reset role;
select * from finish();
rollback;
